<?php
declare(strict_types=1);
require_once __DIR__.'/../../lib/helpers.php';require_once __DIR__.'/../../lib/admin.php';require_once __DIR__.'/../../lib/crypto.php';
send_cors_headers();if(($_SERVER['REQUEST_METHOD']??'')!=='POST')json_response(405,['success'=>false,'message'=>'Method not allowed.']);$body=get_json_body();$email=strtolower(trim((string)($body['email']??'')));$password=(string)($body['password']??'');
if(!is_valid_email($email)||$password==='')json_response(422,['success'=>false,'message'=>'Enter a valid email and password.']);$stmt=get_db()->prepare('SELECT * FROM admin_users WHERE email=:email LIMIT 1');$stmt->execute(['email'=>$email]);$admin=$stmt->fetch();
if(!$admin||!password_verify($password,$admin['password_hash'])){if(rate_limit('admin-login|'.request_ip().'|'.$email,8,900))json_response(429,['success'=>false,'message'=>'Too many attempts. Try again later.']);json_response(401,['success'=>false,'message'=>'The sign-in details are incorrect.']);}if($admin['status']!=='active')json_response(403,['success'=>false,'message'=>'This administrator account is not active.']);
if(!empty($admin['mfa_secret_encrypted'])){$token=rtrim(strtr(base64_encode(random_bytes(36)),'+/','-_'),'=');$challenge=uuid_string();get_db()->prepare('INSERT INTO admin_mfa_challenges (id,admin_id,token_hash,expires_at,created_at) VALUES (:id,:admin,:hash,DATE_ADD(UTC_TIMESTAMP(),INTERVAL 5 MINUTE),UTC_TIMESTAMP())')->execute(['id'=>$challenge,'admin'=>$admin['id'],'hash'=>session_hash($token)]);json_response(202,['success'=>true,'mfa_required'=>true,'challenge_token'=>$token,'redirect'=>'verify.php']);}
$session=create_auth_session('admin',$admin['id'],false);get_db()->prepare('UPDATE admin_users SET last_login_at=UTC_TIMESTAMP() WHERE id=:id')->execute(['id'=>$admin['id']]);audit_event('admin.login','admin',$admin['id'],[],['type'=>'admin','id'=>$admin['id']]);json_response(200,['success'=>true,'admin'=>public_admin($admin),'csrf_token'=>$session['csrf_token'],'redirect'=>'../index.php']);
